package com.jnapanam.sportszone.loyalty.controller;import com.jnapanam.sportszone.loyalty.dto.LoyaltyResponse;import com.jnapanam.sportszone.loyalty.service.LoyaltyService;import java.util.UUID;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/loyalty")public class LoyaltyController{private final LoyaltyService service;public LoyaltyController(LoyaltyService s){service=s;}@GetMapping("/me")public LoyaltyResponse mine(Authentication a){return service.mine(UUID.fromString(a.getName()));}}
